CAT = "dethVorfahrt"; SEG = "VOR"
# Vorfahrt und Vorrang.
Q = [
("An einer Kreuzung gibt es weder Ampeln noch Verkehrszeichen. Von rechts kommt ein Auto. Wer darf zuerst fahren?",
 "Das Auto von rechts", ["Sie, weil Sie schneller sind", "Wer zuerst an der Kreuzung ist", "Wer auf der breiteren Straße fährt"],
 "§ 8 Abs. 1 StVO: An Kreuzungen und Einmündungen ohne Regelung gilt „rechts vor links“. Die Breite der Straße spielt keine Rolle."),
("Vor einer Kreuzung steht Zeichen 205 (Vorfahrt gewähren). Was müssen Sie tun?",
 "Den Querverkehr durchfahren lassen", ["In jedem Fall an der Linie halten", "Nur Fahrzeugen von rechts Vorfahrt lassen", "Mit Vorfahrt weiterfahren"],
 "Zeichen 205 verlangt, die Vorfahrt zu gewähren. Anhalten müssen Sie nur, wenn Querverkehr kommt oder die Sicht es erfordert."),
("Vor einer Einmündung steht Zeichen 206 (Halt. Vorfahrt gewähren.). Die Straße ist frei. Was ist richtig?",
 "An der Haltlinie anhalten, dann fahren", ["Langsam ohne Halt weiterfahren", "Nur bei erkennbarem Querverkehr anhalten", "Hupen und zügig einbiegen"],
 "Zeichen 206 schreibt immer einen vollständigen Halt vor, auch wenn kein Querverkehr zu sehen ist. Danach gewähren Sie Vorfahrt."),
("Sie sehen Zeichen 301, ein rot umrandetes weißes Dreieck mit der Spitze nach oben, darin ein breiter schwarzer senkrechter Balken mit schmalem Querbalken. Was gilt?",
 "Vorfahrt an der nächsten Kreuzung", ["Vorfahrt auf der ganzen Straße", "Vorfahrt gewähren an der Kreuzung", "Ende der Vorfahrtstraße"],
 "Zeichen 301 gibt Ihnen nur an der nächsten Kreuzung oder Einmündung die Vorfahrt. Danach gilt wieder die allgemeine Regel."),
("Auf einer Vorfahrtstraße zeigt ein Zusatzzeichen, dass die Vorfahrt nach links abknickt. Sie folgen dem Straßenverlauf nach links. Was tun Sie?",
 "Links blinken", ["Gar nicht blinken", "Rechts blinken", "Warnblinklicht einschalten"],
 "Wer der abknickenden Vorfahrt folgt, muss das rechtzeitig mit dem Blinker ankündigen, obwohl er die Vorfahrt behält."),
("An einer Kreuzung zeigt Ihre Ampel Grün. Unter der Ampel ist Zeichen 205 angebracht. Was gilt?",
 "Die Ampel", ["Das Zeichen 205", "Rechts vor links", "Wer zuerst kommt"],
 "§ 37 Abs. 1 StVO: Lichtzeichen gehen Vorrangregeln und Vorrang regelnden Verkehrszeichen vor. Das Zeichen gilt erst, wenn die Ampel aus ist."),
("Ein Polizeibeamter regelt eine Kreuzung mit funktionierender Ampel. Wessen Anweisung befolgen Sie?",
 "Die des Polizeibeamten", ["Die der Ampel", "Die der Verkehrszeichen", "Die des Vorausfahrenden"],
 "§ 36 Abs. 1 StVO: Zeichen und Weisungen der Polizeibeamten gehen allen anderen Anordnungen und Regeln vor."),
("Ein Polizeibeamter steht an der Kreuzung und hat beide Arme seitlich quer zu Ihrer Fahrtrichtung ausgestreckt. Was bedeutet das für Sie?",
 "Halt vor der Kreuzung", ["Freie Fahrt geradeaus", "Kreuzung zügig räumen", "Nur Rechtsabbiegen erlaubt"],
 "§ 36 Abs. 2 StVO: Seitliches Ausstrecken der Arme quer zur Fahrtrichtung bedeutet „Halt vor der Kreuzung“, der Querverkehr ist freigegeben."),
("Ein Polizeibeamter hebt einen Arm hoch. Sie befinden sich bereits in der Kreuzung. Was tun Sie?",
 "Die Kreuzung räumen", ["Sofort in der Kreuzung anhalten", "Zurücksetzen bis zur Haltlinie", "Auf das nächste Zeichen in der Kreuzung warten"],
 "Hochheben eines Armes heißt vor der Kreuzung warten. Wer schon in der Kreuzung ist, muss sie räumen."),
("Die Ampel zeigt Rot, daneben ist ein grüner Pfeil auf schwarzem Schild (Zeichen 720) angebracht. Sie wollen rechts abbiegen. Was ist richtig?",
 "Anhalten, dann vorsichtig abbiegen", ["Ohne Halt zügig abbiegen", "Bis zum Grünlicht der Ampel warten", "Nur bei Nacht abbiegen"],
 "§ 37 Abs. 2 StVO: Beim Grünpfeilschild darf nach dem Anhalten rechts abgebogen werden, wenn niemand behindert oder gefährdet wird."),
("Sie biegen an einer Kreuzung links ab. Ein Auto kommt Ihnen entgegen und fährt geradeaus. Wer hat Vorrang?",
 "Das entgegenkommende Auto", ["Sie als Linksabbieger", "Wer zuerst blinkt", "Wer von rechts kommt"],
 "§ 9 Abs. 3 StVO: Wer abbiegen will, muss entgegenkommende Fahrzeuge durchfahren lassen."),
("Sie wollen rechts abbiegen. Neben Ihnen fährt ein Radfahrer auf dem Radweg geradeaus. Was gilt?",
 "Sie lassen den Radfahrer durchfahren", ["Sie haben Vorrang, weil Sie blinken", "Der Radfahrer muss für Sie bremsen und warten", "Wer zuerst die Ecke erreicht"],
 "§ 9 Abs. 3 StVO: Abbiegende müssen auch Radfahrer auf Radwegen durchfahren lassen, die in gleicher Richtung geradeaus fahren."),
("Sie biegen rechts ab. Fußgänger überqueren gerade die Straße, in die Sie einbiegen wollen. Was tun Sie?",
 "Warten, bis sie hinüber sind", ["Langsam zwischen ihnen durchfahren", "Hupen und weiterfahren", "Weiterfahren, Sie haben Grün"],
 "§ 9 Abs. 3 StVO: Auf Fußgänger ist beim Abbiegen besondere Rücksicht zu nehmen, wenn nötig ist zu warten."),
("Ein Fußgänger steht erkennbar wartend an einem Fußgängerüberweg (Zebrastreifen). Was müssen Sie tun?",
 "Anhalten und ihn gehen lassen", ["Weiterfahren, er wartet ja", "Hupen, damit er wartet", "Nur bei Dunkelheit anhalten"],
 "§ 26 Abs. 1 StVO: Wer erkennbar einen Fußgängerüberweg benutzen will, hat Vorrang. Sie müssen mit mäßiger Geschwindigkeit heranfahren und, wenn nötig, warten."),
("An einem Kreisverkehr stehen Zeichen 215 (Kreisverkehr) und Zeichen 205. Wer hat Vorfahrt?",
 "Wer im Kreisverkehr fährt", ["Wer in den Kreis einfährt", "Wer von rechts kommt", "Wer den Kreis verlassen will"],
 "Mit Zeichen 205 müssen Einfahrende den Fahrzeugen im Kreisverkehr die Vorfahrt gewähren."),
("Ein Traktor kommt aus einem Feldweg und will in Ihre Landstraße einbiegen. Wer hat Vorfahrt?",
 "Sie auf der Landstraße", ["Der Traktor, weil er von rechts kommt", "Der Traktor, weil er langsamer ist", "Wer zuerst an der Einmündung ist"],
 "§ 8 Abs. 1 StVO: Wer aus einem Feld- oder Waldweg auf eine andere Straße kommt, hat keine Vorfahrt, auch wenn er von rechts kommt."),
("Sie fahren aus einer Grundstücksausfahrt auf die Straße. Was gilt für Sie?",
 "Niemand darf gefährdet werden", ["Rechts vor links gilt für Sie", "Sie haben Vorfahrt nach links", "Fußgänger müssen warten"],
 "§ 10 StVO: Wer aus einem Grundstück, über einen abgesenkten Bordstein oder aus einem verkehrsberuhigten Bereich kommt, muss eine Gefährdung anderer ausschließen."),
("Sie verlassen einen verkehrsberuhigten Bereich (Zeichen 325.2 steht am Ende). Wer hat Vorrang?",
 "Der Verkehr auf der Straße", ["Sie, wenn Sie von rechts kommen", "Sie, wenn die Straße schmaler ist", "Wer zuerst blinkt"],
 "Beim Ausfahren aus einem verkehrsberuhigten Bereich gilt § 10 StVO wie bei einer Grundstücksausfahrt: Sie lassen allen anderen den Vortritt."),
("Innerorts blinkt ein Linienbus und will von einer gekennzeichneten Haltestelle abfahren. Was müssen Sie tun?",
 "Ihm das Abfahren ermöglichen", ["Schnell an ihm vorbeifahren, bevor er losfährt", "Hupen, damit er wartet", "Nur bei Schulbussen bremsen"],
 "§ 20 Abs. 5 StVO: Linienbussen und Schulbussen ist das Abfahren von gekennzeichneten Haltestellen zu ermöglichen, wenn nötig müssen Sie warten."),
("Vor einer Engstelle steht für Sie Zeichen 208 (Dem Gegenverkehr Vorrang gewähren). Ein Auto kommt entgegen. Was tun Sie?",
 "Vor der Engstelle warten", ["Zügig in die Engstelle fahren", "Mit Lichthupe Vorrang verlangen", "Halb auf den Gehweg ausweichen"],
 "Zeichen 208 gibt dem Gegenverkehr den Vorrang. Sie warten, bis die Engstelle frei ist."),
("Vor einer Engstelle steht für Sie Zeichen 308, ein blaues Quadrat mit großem weißem und kleinem rotem Pfeil. Was bedeutet es?",
 "Sie haben Vorrang vor dem Gegenverkehr", ["Sie müssen dem Gegenverkehr Vorrang lassen", "Die Straße wird zur Einbahnstraße", "Es beginnt ein Fahrstreifen"],
 "Zeichen 308 gibt Ihnen an der Engstelle Vorrang. Rechnen Sie trotzdem damit, dass jemand den Vorrang nicht beachtet."),
("Sie und ein entgegenkommendes Fahrzeug wollen an einer Kreuzung beide links abbiegen. Wie biegen Sie in der Regel ab?",
 "Voreinander", ["Hintereinander", "Wer zuerst blinkt, fährt allein", "Beide halten und warten"],
 "§ 9 Abs. 4 StVO: Einander entgegenkommende Linksabbieger biegen voreinander ab, wenn die Verkehrslage oder Markierungen nichts anderes verlangen."),
("Sie fahren über einen Beschleunigungsstreifen auf die Autobahn. Wer hat Vorfahrt?",
 "Der Verkehr auf der Autobahn", ["Sie als Einfahrender", "Wer schneller fährt", "Wer zuerst blinkt"],
 "§ 18 Abs. 3 StVO: Der Verkehr auf der durchgehenden Fahrbahn hat Vorfahrt. Passen Sie Ihr Tempo an und nutzen Sie eine Lücke."),
("Die Ampel ist ausgefallen. Am Ampelmast ist Zeichen 205 angebracht. Was gilt für Sie?",
 "Das Zeichen 205", ["Rechts vor links", "Wer zuerst kommt", "Die Ampel gilt als Grün"],
 "Ist die Ampel außer Betrieb, gelten die darunter oder am Mast angebrachten Vorfahrtzeichen."),
("Eine Ampel zeigt gelbes Blinklicht. Was bedeutet das?",
 "Vorsicht, die Zeichen regeln die Vorfahrt", ["Halt wie bei Rot", "Freie Fahrt mit Vorrang vor dem Querverkehr", "Die Kreuzung ist gesperrt"],
 "Gelbes Blinklicht warnt nur. Die Vorfahrt richtet sich dann nach den Verkehrszeichen oder nach „rechts vor links“."),
("An einer Kreuzung steht Zeichen 102, ein rot umrandetes Dreieck mit schwarzem Schrägkreuz. Was gilt dort?",
 "Rechts vor links", ["Sie haben Vorfahrt", "Sie müssen anhalten", "Fußgänger haben Vorrang"],
 "Zeichen 102 warnt vor einer Kreuzung oder Einmündung mit Vorfahrt von rechts."),
("Ein Fahrzeug mit eingeschaltetem Blaulicht, aber ohne Martinshorn fährt hinter Ihnen. Was gilt?",
 "Kein Wegerecht, aber aufmerksam sein", ["Sie müssen sofort freie Bahn schaffen", "Sie müssen anhalten", "Sie dürfen nicht weiterfahren"],
 "Freie Bahn ist nach § 38 StVO zu schaffen, wenn Blaulicht und Einsatzhorn zusammen eingeschaltet sind. Blaulicht allein warnt vor Gefahren."),
("An einer Kreuzung ohne Verkehrszeichen wollen Sie links abbiegen. Von rechts nähert sich ein Radfahrer. Wer hat Vorfahrt?",
 "Der Radfahrer", ["Sie, weil Sie ein Auto fahren", "Wer schneller ist", "Sie, weil Sie zuerst blinken"],
 "Auch Radfahrer haben „rechts vor links“. Die Vorfahrtregeln gelten für alle Fahrzeuge gleich."),
]
